    async def answer(
        self,
        co: str,
        id: str,
        *,
        answers: Sequence[params.ChatChoiceAnswer],
        choice_id: str,
        request_options: RequestOptions | None = None,
    ) -> ChatTurnResult:
        """Ответ на уточняющий вопрос ИИ (событие choice)

        Продолжает ход потоком SSE. Повторный ответ на тот же choice_id — 409 (error.turn — номер хода с ответом; error.code = dismissed — вопрос закрыт без ответа). Отказы: 402 — ИИ компании не подключён (не оплачено подключение); 409 — идёт предыдущий ход или разговор закрыт (error.code = dialog_closed); 410 — разговор не найден или истёк, начните новый; 429 — кончился лимит тарифа (plan_limit_reached) или у человека уже идёт предельное число ходов без доп. использования (parallel_turns_limit, Retry-After; ход не начат); 503 — сервис модели не настроен.

        Доступ: chat.use.

        Доступно по ключу API.

        Args:
            co: id компании, co_… — из GET /v1/companies
            id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
            answers: Ответы — по одному на каждый вопрос, в том же порядке, что questions
            choice_id: id вопроса — choice_id из события choice (или из awaiting / pending_question)
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request(
            RequestSpec(
                method="POST",
                path=f"/v1/companies/{path_segment('co', co)}/chat/{path_segment('id', id)}/answer",
                body=json_body(
                    {
                        "answers": answers,
                        "choice_id": choice_id,
                        "stream": False,
                    }
                ),
                long_running=True,
            ),
            cast_to=ChatTurnResult,
            options=request_options,
        )

    async def answer_stream(
        self,
        co: str,
        id: str,
        *,
        answers: Sequence[params.ChatChoiceAnswer],
        choice_id: str,
        request_options: RequestOptions | None = None,
    ) -> AsyncChatStream:
        """Ответ на уточняющий вопрос ИИ (событие choice)

        Продолжает ход потоком SSE. Повторный ответ на тот же choice_id — 409 (error.turn — номер хода с ответом; error.code = dismissed — вопрос закрыт без ответа). Отказы: 402 — ИИ компании не подключён (не оплачено подключение); 409 — идёт предыдущий ход или разговор закрыт (error.code = dialog_closed); 410 — разговор не найден или истёк, начните новый; 429 — кончился лимит тарифа (plan_limit_reached) или у человека уже идёт предельное число ходов без доп. использования (parallel_turns_limit, Retry-After; ход не начат); 503 — сервис модели не настроен.

        Доступ: chat.use.

        Доступно по ключу API.

        Streaming variant: returns the events of the turn as they arrive.

        Args:
            co: id компании, co_… — из GET /v1/companies
            id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
            answers: Ответы — по одному на каждый вопрос, в том же порядке, что questions
            choice_id: id вопроса — choice_id из события choice (или из awaiting / pending_question)
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request_chat_stream(
            RequestSpec(
                method="POST",
                path=f"/v1/companies/{path_segment('co', co)}/chat/{path_segment('id', id)}/answer",
                body=json_body(
                    {
                        "answers": answers,
                        "choice_id": choice_id,
                        "stream": True,
                    }
                ),
            ),
            options=request_options,
        )

    async def list_events(
        self,
        co: str,
        id: str,
        *,
        turn: int | None | Omit = omit,
        request_options: RequestOptions | None = None,
    ) -> AsyncChatStream:
        """Переподключиться к идущему ходу

        Переподключение — с заголовком Last-Event-ID: события до него не повторяются. Ход уже сменился (turn не совпал) — 409 с error.turn. Хода нет (закончен и выгружен) — 404: откройте разговор GET …/chat/{id}. Ход идёт на другом сервере Tungo (несколько экземпляров за балансировщиком) — поток из status (code elsewhere) и, когда ход закончится, done со stop_reason elsewhere: ответ тогда — в GET …/chat/{id}.

        Доступ: chat.use.

        Доступно по ключу API.

        Args:
            co: id компании, co_… — из GET /v1/companies
            id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
            turn: Номер хода (X-Turn-No), к которому переподключиться; без него — к текущему
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request_chat_stream(
            RequestSpec(
                method="GET",
                path=f"/v1/companies/{path_segment('co', co)}/chat/{path_segment('id', id)}/events",
                query=query_params(
                    {
                        "turn": turn,
                    }
                ),
            ),
            options=request_options,
        )

    async def download_file(
        self,
        co: str,
        id: str,
        file: str,
        *,
        request_options: RequestOptions | None = None,
    ) -> DownloadedFile:
        """Скачать файл, собранный ИИ

        Файл из события file (и блока file истории): Excel, Word, PDF или CSV. Скачать может только владелец разговора — как сам разговор; удалили разговор — файла больше нет (404). Ответ — сам файл: Content-Disposition attachment, русское имя — в filename* (UTF-8), латинское запасное — в filename. В Excel формула одна — «Итого» (СУММ), значения из 1С формулами не становятся.

        Доступ: chat.use.

        Доступно по ключу API.

        Returns the downloaded file: its bytes, its name from Content-Disposition and its content type.

        Args:
            co: id компании, co_… — из GET /v1/companies
            id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
            file: id файла (file_…)
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request_download(
            RequestSpec(
                method="GET",
                path=f"/v1/companies/{path_segment('co', co)}/chat/{path_segment('id', id)}/files/{path_segment('file', file)}",
            ),
            options=request_options,
        )

    async def stop(
        self,
        co: str,
        id: str,
        *,
        request_options: RequestOptions | None = None,
    ) -> ChatStopResult:
        """Остановить ход или закрыть открытый вопрос

        Идёт ход — останавливается (поток получит ошибку aborted и done). Ход ждёт ответа на вопрос — вопрос закрывается без ответа (dismissed: true). Ни хода, ни вопроса — 404.

        Доступ: chat.use.

        Доступно по ключу API.

        Args:
            co: id компании, co_… — из GET /v1/companies
            id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request(
            RequestSpec(
                method="POST",
                path=f"/v1/companies/{path_segment('co', co)}/chat/{path_segment('id', id)}/stop",
            ),
            cast_to=ChatStopResult,
            options=request_options,
        )


